func:
// Mappa entita' -> alert. Ritorna null se lo stato non merita il display.
// icon: washing | bell | door | power | mower | air | ev | alert
// r,g,b: colore della riga principale   seconds: durata a schermo
//
// Per aggiungere un evento: duplica un nodo trigger, punta la tua entita',
// e aggiungi qui sotto una riga con lo stesso entity_id.

const T = {

  "sensor.washing_machine_status": s =>
    s === "Fine"
      ? { icon: "washing", line1: "LAVATRICE", line2: "finita",
          r: 0, g: 200, b: 255, seconds: 25 }
      : null,

  "binary_sensor.campanello_visitatore": s =>
    s === "on"
      ? { icon: "bell", line1: "CAMPANELLO", line2: "",
          r: 255, g: 190, b: 40, seconds: 20 }
      : null,

  "binary_sensor.sensore_porta_1": s =>
    s === "on"
      ? { icon: "door", line1: "INGRESSO", line2: "aperta",
          r: 255, g: 120, b: 0, seconds: 30 }
      : null,

  "binary_sensor.sensore_porta_9": s =>
    s === "on"
      ? { icon: "door", line1: "RETRO", line2: "aperta",
          r: 255, g: 120, b: 0, seconds: 30 }
      : null,

  "lawn_mower.tagliaerba": s =>
    /error|fault|stuck|blocc|errore/i.test(s)
      ? { icon: "mower", line1: "RASAERBA", line2: "errore",
          r: 255, g: 50, b: 40, seconds: 45 }
      : null
};

const fn = T[msg.topic];
if (!fn) { return null; }

const alert = fn(String(msg.payload));
if (!alert) { return null; }

// antirimbalzo: non ripetere lo stesso alert entro 60 s
const key = msg.topic + "|" + alert.line1 + alert.line2;
const last = flow.get("m1_last") || {};
const now = Date.now();
if (last[key] && now - last[key] < 60000) { return null; }
last[key] = now;
flow.set("m1_last", last);

msg.payload = {
  domain: "esphome",
  service: "m1_matrix_show_alert",
  data: alert
};
return msg;
